<script setup lang="ts">
import TableSortHeader from '@/components/TableSortHeader.vue'
import TablePager from '@/components/TablePager.vue'
import {useClientTable} from '@/features/table/useClientTable'
import {useColumnWidths} from '@/features/table/useColumnWidths'
import {useDebouncedValue} from '@/features/table/useTableView'

import {ref,reactive,computed,onMounted,watch} from 'vue'
import {submissionId} from '@/utils/submissionId'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useAuthStore} from '@/stores/auth'
import {ops,listOps,stockStates,moveLabels,errorMessage,exportSheet,printAssetLabels} from '@/api/asset-ops'
import '@/styles/asset-ops.css'
import SpareMovementTable from '@/components/SpareMovementTable.vue'
import SpareReceiptDialog from '@/components/SpareReceiptDialog.vue'
const auth=useAuthStore(),tab=ref('stocks'),stocks=ref<any[]>([]),specs=ref<any[]>([]),sites=ref<any[]>([]),minimums=ref<any[]>([]),movements=ref<any[]>([]),devices=ref<any[]>([]),selected=ref<any[]>([]),loading=ref(false),busy=ref(false)
const settingsOpen=ref(false),settingsTab=ref('specs'),detailOpen=ref(false),detailTab=ref('info'),detailId=ref('')
const detailStock=computed(()=>stocks.value.find(s=>s.id===detailId.value))
const detailMovements=computed(()=>movements.value.filter(m=>m.stockId===detailId.value||m.destinationStockId===detailId.value))
function showDetail(row:any){detailId.value=row.id;detailTab.value='info';detailOpen.value=true}
function stockAction(row:any,action:string){if(action==='EDIT')editRecord('stock',row);else if(action==='DELETE')removeRecord('stock',row);else operate(row,action)}
const receiptDialog=ref(false),historyTarget=ref<any>(null)
const historyRows=computed(()=>historyTarget.value?movements.value.filter(m=>m.stockId===historyTarget.value.id||m.destinationStockId===historyTarget.value.id):movements.value)
function showHistory(row:any){historyTarget.value=row;tab.value='movements'}
const editing=ref(false)
const identityLocked=computed(()=>editing.value&&kind.value==='stock'&&(!isEmptyDraft(current.value)||hasStockMovement(current.value?.id)))
const specHasStock=computed(()=>editing.value&&kind.value==='spec'&&stocks.value.some(x=>x.specId===current.value?.id))
function isEmptyDraft(row:any){return row&&row.quantity===0&&row.state==='AVAILABLE'&&!row.installedDeviceId&&!row.destinationSiteId}
function hasStockMovement(id:string){return movements.value.some(m=>m.stockId===id||m.destinationStockId===id)}
const filter=reactive({search:'',region:'',category:'',siteId:'',state:''}),dialog=ref(false),kind=ref(''),form=reactive<any>({}),current=ref<any>(null)
const canWrite=computed(()=>auth.user?.roles?.some(r=>['system_admin','asset_manager'].includes(r.code)))
let loadRequest=0
const loadFailed=ref(false)
async function load(){const request=++loadRequest;loading.value=true;loadFailed.value=false;try{const next=await Promise.all(['stocks','specs','sites','minimums','movements','devices'].map(listOps));if(request!==loadRequest)return;[stocks.value,specs.value,sites.value,minimums.value,movements.value,devices.value]=next;clearStockSelection()}catch(e){if(request===loadRequest){loadFailed.value=true;ElMessage.error(errorMessage(e))}}finally{if(request===loadRequest)loading.value=false}}
const regions=computed(()=>[...new Set(sites.value.map(s=>s.region))].filter(Boolean))
const categories=computed(()=>[...new Set(specs.value.map(s=>s.category))].filter(Boolean))
const currentSpec=computed(()=>specs.value.find(s=>s.id===form.specId))
const stockQuery=useDebouncedValue(()=>filter.search)
const filtered=computed(()=>stocks.value.filter(x=>(!filter.region||x.site.region===filter.region)&&(!filter.category||x.spec.category===filter.category)&&(!filter.siteId||x.siteId===filter.siteId)&&(!filter.state||x.state===filter.state)&&(!stockQuery.value||[x.serialNumber,x.spec.name,x.spec.modelNumber,x.spec.partNumber,x.notes].join(' ').toLowerCase().includes(stockQuery.value.toLowerCase()))))
const metrics=computed(()=>({available:stocks.value.filter(x=>x.state==='AVAILABLE').reduce((n,x)=>n+x.quantity,0),reserved:stocks.value.filter(x=>x.state==='RESERVED').reduce((n,x)=>n+x.quantity,0),transit:stocks.value.filter(x=>x.state==='TRANSIT').reduce((n,x)=>n+x.quantity,0),testing:stocks.value.filter(x=>['TESTING','FAULTY'].includes(x.state)).reduce((n,x)=>n+x.quantity,0)}))
const summary=computed(()=>{const map=new Map<string,any>();for(const x of stocks.value){const key=x.siteId+':'+x.specId;const row=map.get(key)||{区域:x.site.region,位置:x.site.name,类型:x.spec.category,备件:x.spec.name,型号:x.spec.modelNumber,料号:x.spec.partNumber,规格:x.spec.specification,可用:0,预留:0,待检测:0,故障:0,在途:0,维修中:0,单位:x.spec.unit};const field:Record<string,string>={AVAILABLE:'可用',RESERVED:'预留',TESTING:'待检测',FAULTY:'故障',TRANSIT:'在途',REPAIR:'维修中'};if(field[x.state])row[field[x.state]]+=x.quantity;map.set(key,row)}return [...map.values()]})
function create(k:string){editing.value=false;current.value=null;kind.value=k;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,({spec:{name:'',category:'硬盘',manufacturer:'',modelNumber:'',partNumber:'',specification:'',tracking:'SERIAL',unit:'件',compatibility:''},minimum:{specId:specs.value[0]?.id,siteId:sites.value[0]?.id,minimum:1}} as any)[k]);dialog.value=true}
function operate(row:any,operation?:string){editing.value=false;kind.value='move';current.value=row;Object.keys(form).forEach(k=>delete form[k]);const choices=allowed(row);Object.assign(form,{version:row.version,submissionId:submissionId(),operation:operation||choices[0],quantity:['RECEIVE','RESERVE','RELEASE','PASS','FAULT','REPAIR','RETIRE'].includes(operation||choices[0])?row.quantity:1,deviceId:null,destinationSiteId:null,reason:'',disposalEvidence:''});dialog.value=true}
function allowed(x:any){const a:string[]=[];if(x.state==='AVAILABLE'){if(x.spec.tracking==='QUANTITY'||!x.quantity)a.push('IN');if(x.quantity)a.push(...(x.spec.tracking==='SERIAL'?['INSTALL']:['OUT']),'TRANSFER','RESERVE','FAULT')}if(x.state==='RESERVED')a.push('RELEASE',...(x.spec.tracking==='SERIAL'?['INSTALL']:[]));if(x.state==='INSTALLED')a.push('REMOVE');if(x.state==='TRANSIT')a.push('RECEIVE');if(['TESTING','REPAIR'].includes(x.state))a.push('PASS','FAULT');if(x.state==='FAULTY')a.push('REPAIR');if(['TESTING','FAULTY'].includes(x.state))a.push('RETIRE');return a}
function secondaryAllowed(row:any){return allowed(row).filter(op=>!['TRANSFER','RECEIVE'].includes(op))}
function editRecord(k:string,row:any){editing.value=true;kind.value=k;current.value=row;Object.keys(form).forEach(key=>delete form[key]);const fields:Record<string,string[]>={spec:['version','name','category','manufacturer','modelNumber','partNumber','specification','tracking','unit','compatibility'],stock:['version','specId','siteId','bin','serialNumber','batch','notes','warrantyExpiresAt'],minimum:['version','specId','siteId','minimum']};for(const key of fields[k]||[])form[key]=row[key];if(k==='stock'){form.quantity=row.quantity;form.state=row.state}if(k==='stock')form.warrantyExpiresAt=row.warrantyExpiresAt?.slice(0,10)||null;dialog.value=true}
async function removeRecord(k:string,row:any){const names:Record<string,string>={spec:'备件规格',stock:'备件空档',minimum:'最低库存规则'};const paths:Record<string,string>={spec:'specs',stock:'stocks',minimum:'minimums'};const text=k==='stock'?'仅可删除未入库、无流水或盘点历史的零库存空档。':k==='spec'?'已被备件档案或库存规则引用的规格不能删除。':'删除后停止该规则的最低库存提醒。';try{await ElMessageBox.confirm('确认删除'+names[k]+'？'+text,'删除确认',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})}catch{return}busy.value=true;try{await ops(`${paths[k]}/${row.id}?version=${row.version}`,'DELETE');await load();ElMessage.success('已删除并保留审计记录')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function save(){busy.value=true;try{const paths:Record<string,string>={spec:'specs',stock:'stocks',minimum:'minimums',move:`stocks/${current.value?.id}/move`};const data={...form};if(editing.value&&kind.value==='stock'){delete data.quantity;delete data.state}if(kind.value==='stock'&&data.warrantyExpiresAt)data.warrantyExpiresAt+='T00:00:00+08:00';const path=editing.value?`${paths[kind.value]}/${current.value.id}`:paths[kind.value];await ops(path,editing.value?'PUT':'POST',editing.value&&kind.value==='minimum'?{version:form.version,minimum:form.minimum}:data);dialog.value=false;await load();ElMessage.success(editing.value?'修改已保存':'操作已完成')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}

const historyTable=ref<{exportRows:()=>any[]}>()
function exportHistory(){exportSheet('库存流水',(historyTable.value?.exportRows()||historyRows.value).map(m=>{const target=historyTarget.value&&m.operation==='TRANSFER'&&m.destinationStockId===historyTarget.value.id;return {单号:m.id,备件:m.stock?.spec?.name,SN:m.stock?.serialNumber,操作:moveLabels[m.operation],数量:m.quantity,操作前:target?0:m.beforeQuantity,操作后:target?m.quantity:m.afterQuantity,原状态:target?'新增调拨批次':stockStates[m.beforeState]||'未记录',新状态:target?'在途':stockStates[m.afterState]||'未记录',来源位置:sites.value.find(s=>s.id===m.sourceSiteId)?.name,目标位置:sites.value.find(s=>s.id===m.destinationSiteId)?.name,依据:m.reason,时间:m.createdAt}}))}
function exportStocks(){exportSheet('机房备件',stockSortedRows.value.map(x=>({库存ID:x.id,名称:x.spec.name,类别:x.spec.category,型号:x.spec.modelNumber,料号:x.spec.partNumber,规格:x.spec.specification,管理方式:x.spec.tracking==='SERIAL'?'按件':'数量',SN:x.serialNumber,区域:x.site.region,备注:x.notes,位置:x.site.name,库位:x.bin,批次:x.batch,状态:stockStates[x.state],数量:x.quantity,可用数量:x.state==='AVAILABLE'?x.quantity:0,单位:x.spec.unit,安装设备:x.installedDevice?.code,保修截止日:x.warrantyExpiresAt})))}
async function labels(){try{await printAssetLabels('stock',selected.value);ElMessage.success('标签已生成，请在标签窗口打印或保存 PDF')}catch(e){ElMessage.error(errorMessage(e))}}
const {page:stockPage,pageSize:stockPageSize,total:stockTotal,pageRows:stockPageRows,sortedRows:stockSortedRows,sortKey:stockSortKey,sortOrder:stockSortOrder,tableRef:stockTable,sortBy:sortStockBy,onSortChange:onStockSortChange}=useClientTable(filtered,{regionLabel:row=>row.site.region+' / '+(row.state==='INSTALLED'?'随关联设备':row.site.name),stateLabel:row=>stockStates[row.state]})
const {columnWidths:stockWidths,resizeColumn:resizeStockColumn}=useColumnWidths({"regionLabel": 160, "spec.category": 100, "spec.name": 160, "spec.modelNumber": 145, "quantity": 95, "serialNumber": 175, "notes": 200, "stateLabel": 110})
const summarySearch=ref(''),summaryQuery=useDebouncedValue(summarySearch)
const summaryFiltered=computed(()=>summary.value.filter(row=>!summaryQuery.value.trim()||[row.区域,row.位置,row.类型,row.备件,row.型号].some(value=>String(value||'').toLowerCase().includes(summaryQuery.value.trim().toLowerCase()))))
function clearSummarySearch(){summarySearch.value='';summaryQuery.value=''}
const {page:summaryPage,pageSize:summaryPageSize,total:summaryTotal,pageRows:summaryPageRows,sortedRows:summarySortedRows,sortKey:summarySortKey,sortOrder:summarySortOrder,tableRef:summaryTable,sortBy:sortSummaryBy,onSortChange:onSummarySortChange}=useClientTable(summaryFiltered,{})
const {columnWidths:summaryWidths,resizeColumn:resizeSummaryColumn}=useColumnWidths({"区域": 170, "位置": 170, "类型": 170, "备件": 170, "型号": 170, "可用": 85, "预留": 85, "待检测": 85, "故障": 85, "在途": 85, "维修中": 85})
const specSearch=ref(''),specQuery=useDebouncedValue(specSearch)
const specFiltered=computed(()=>specs.value.filter(row=>!specQuery.value.trim()||[row.name,row.partNumber,row.specification,row.compatibility].some(value=>String(value||'').toLowerCase().includes(specQuery.value.trim().toLowerCase()))))
function clearSpecSearch(){specSearch.value='';specQuery.value=''}
const {page:specPage,pageSize:specPageSize,total:specTotal,pageRows:specPageRows,sortedRows:specSortedRows,sortKey:specSortKey,sortOrder:specSortOrder,tableRef:specTable,sortBy:sortSpecBy,onSortChange:onSpecSortChange}=useClientTable(specFiltered,{trackingLabel:row=>row.tracking==='SERIAL'?'按件 / SN':'按数量'})
const {columnWidths:specWidths,resizeColumn:resizeSpecColumn}=useColumnWidths({"name": 160, "partNumber": 160, "specification": 220, "trackingLabel": 110, "compatibility": 200})
const minimumSearch=ref(''),minimumQuery=useDebouncedValue(minimumSearch)
const minimumFiltered=computed(()=>minimums.value.filter(row=>!minimumQuery.value.trim()||[row.site?.name,row.spec?.name,row.spec?.specification].some(value=>String(value||'').toLowerCase().includes(minimumQuery.value.trim().toLowerCase()))))
function clearMinimumSearch(){minimumSearch.value='';minimumQuery.value=''}
const {page:minimumPage,pageSize:minimumPageSize,total:minimumTotal,pageRows:minimumPageRows,sortedRows:minimumSortedRows,sortKey:minimumSortKey,sortOrder:minimumSortOrder,tableRef:minimumTable,sortBy:sortMinimumBy,onSortChange:onMinimumSortChange}=useClientTable(minimumFiltered,{specLabel:row=>(row.spec.name||'')+' / '+(row.spec.specification||'')})
const {columnWidths:minimumWidths,resizeColumn:resizeMinimumColumn}=useColumnWidths({"site.name": 160, "specLabel": 160, "minimum": 160})
function clearStockSelection(){stockTable.value?.clearSelection();selected.value=[]}
function clearStockFilters(){filter.search='';stockQuery.value='';filter.region='';filter.category='';filter.siteId='';filter.state='';clearStockSelection()}
watch([stockPage,stockPageSize,stockSortKey,stockSortOrder,filtered],clearStockSelection)
onMounted(load)
</script>
<template><div class="asset-ops"><div class="ops-heading"><div><span class="ops-eyebrow">SPARE PARTS MANAGEMENT</span><h1>机房备件</h1><p>直接录入备件，按区域查看库存；点开详情即可追溯档案、状态和流水。</p></div><div><el-button @click="settingsOpen=true">资料与预警设置</el-button><el-button :disabled="loading||loadFailed||filter.search!==stockQuery" @click="exportStocks">导出库存</el-button><el-button v-if="canWrite" type="primary" @click="receiptDialog=true">录入备件</el-button></div></div><div class="ops-metrics"><div><span>可用库存</span><b>{{metrics.available}}</b></div><div><span>已预留</span><b>{{metrics.reserved}}</b></div><div><span>在途待收货</span><b>{{metrics.transit}}</b></div><div><span>待检测 / 故障</span><b>{{metrics.testing}}</b></div></div><el-alert v-if="loadFailed" title="加载失败，当前行可能不是最新库存；请刷新重试" type="error" :closable="false"/><el-button v-if="loadFailed" @click="load">刷新重试</el-button><el-card shadow="never" v-loading="loading"><el-tabs v-model="tab"><el-tab-pane label="库存明细" name="stocks"><div class="ops-toolbar"><el-input v-model="filter.search" clearable placeholder="名称 / SN / 型号 / 料号 / 备注" @input="clearStockSelection"/><el-select v-model="filter.region" clearable placeholder="全部区域" @change="filter.siteId=''"><el-option v-for="r in regions" :key="r" :label="r" :value="r"/></el-select><el-select v-model="filter.category" clearable placeholder="全部类型"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select><el-select v-model="filter.siteId" clearable placeholder="全部位置"><el-option v-for="s in sites.filter(s=>!filter.region||s.region===filter.region)" :key="s.id" :label="s.region+' / '+s.name" :value="s.id"/></el-select><el-select v-model="filter.state" clearable placeholder="全部状态"><el-option v-for="(v,k) in stockStates" :key="k" :label="v" :value="k"/></el-select><el-button :disabled="!selected.length||loading||loadFailed||filter.search!==stockQuery" @click="labels">打印标签</el-button></div><el-table :data="stockPageRows" ref="stockTable" @sort-change="onStockSortChange" row-key="id" :empty-text="stocks.length?'没有匹配的备件，请调整筛选条件':canWrite?'暂无备件，点击上方录入备件开始登记':'暂无备件记录'" @selection-change="selected=$event"><el-table-column type="selection" width="45"/><el-table-column label="区域" prop="regionLabel" sortable="custom" :width="stockWidths['regionLabel']"><template #header><TableSortHeader label="区域" :width="stockWidths['regionLabel']" @sort="sortStockBy('regionLabel')" @resize="resizeStockColumn('regionLabel',$event)"/></template><template #default="{row}">{{row.site.region}}<small class="ops-block ops-muted">{{row.state==='INSTALLED'?'随关联设备':row.site.name}}</small></template></el-table-column><el-table-column label="类型" prop="spec.category" sortable="custom" :width="stockWidths['spec.category']"><template #header><TableSortHeader label="类型" :width="stockWidths['spec.category']" @sort="sortStockBy('spec.category')" @resize="resizeStockColumn('spec.category',$event)"/></template></el-table-column><el-table-column label="名称" prop="spec.name" sortable="custom" :width="stockWidths['spec.name']"><template #header><TableSortHeader label="名称" :width="stockWidths['spec.name']" @sort="sortStockBy('spec.name')" @resize="resizeStockColumn('spec.name',$event)"/></template></el-table-column><el-table-column label="型号" prop="spec.modelNumber" sortable="custom" :width="stockWidths['spec.modelNumber']"><template #header><TableSortHeader label="型号" :width="stockWidths['spec.modelNumber']" @sort="sortStockBy('spec.modelNumber')" @resize="resizeStockColumn('spec.modelNumber',$event)"/></template></el-table-column><el-table-column label="数量" prop="quantity" sortable="custom" :width="stockWidths['quantity']"><template #header><TableSortHeader label="数量" :width="stockWidths['quantity']" @sort="sortStockBy('quantity')" @resize="resizeStockColumn('quantity',$event)"/></template><template #default="{row}"><b>{{row.quantity}}</b> {{row.spec.unit}}</template></el-table-column><el-table-column label="序列号" prop="serialNumber" sortable="custom" :width="stockWidths['serialNumber']"><template #header><TableSortHeader label="序列号" :width="stockWidths['serialNumber']" @sort="sortStockBy('serialNumber')" @resize="resizeStockColumn('serialNumber',$event)"/></template><template #default="{row}"><span class="ops-mono">{{row.serialNumber||'按数量管理'}}</span></template></el-table-column><el-table-column label="备注" show-overflow-tooltip prop="notes" sortable="custom" :width="stockWidths['notes']"><template #header><TableSortHeader label="备注" :width="stockWidths['notes']" @sort="sortStockBy('notes')" @resize="resizeStockColumn('notes',$event)"/></template></el-table-column><el-table-column label="状态" prop="stateLabel" sortable="custom" :width="stockWidths['stateLabel']"><template #header><TableSortHeader label="状态" :width="stockWidths['stateLabel']" @sort="sortStockBy('stateLabel')" @resize="resizeStockColumn('stateLabel',$event)"/></template><template #default="{row}"><el-tag :type="row.state==='AVAILABLE'?'success':['TESTING','FAULTY'].includes(row.state)?'warning':'info'">{{stockStates[row.state]}}</el-tag></template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">详情</el-button><template v-if="canWrite"><el-button v-if="allowed(row).includes('TRANSFER')" link type="primary" :disabled="busy" @click="operate(row,'TRANSFER')">调拨</el-button><el-button v-if="allowed(row).includes('RECEIVE')" link type="success" :disabled="busy" @click="operate(row,'RECEIVE')">确认收货</el-button><el-dropdown trigger="click" @command="stockAction(row,$event)"><el-button link type="primary">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="EDIT">编辑档案</el-dropdown-item><el-dropdown-item v-for="op in secondaryAllowed(row)" :key="op" :command="op">{{op==='IN'?'补充入库':moveLabels[op]}}</el-dropdown-item><el-dropdown-item v-if="isEmptyDraft(row)&&!hasStockMovement(row.id)" command="DELETE" divided>删除空档</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></template></el-table-column><template #empty><el-empty :description="stocks.length?'没有匹配的备件':'暂无备件记录'"><el-button v-if="stockQuery||filter.region||filter.category||filter.siteId||filter.state" @click="clearStockFilters">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="stockPage" v-model:page-size="stockPageSize" :total="stockTotal" label="库存明细"/></el-tab-pane>
<el-tab-pane label="机房统计" name="summary"><div class="ops-toolbar between"><p class="ops-muted">已安装备件作为设备部件，不计入可用库存；在途、预留、外修分开统计。</p><el-button :disabled="loading||loadFailed||summarySearch!==summaryQuery" @click="exportSheet('分机房备件统计',summarySortedRows)">导出统计</el-button></div><el-input v-model="summarySearch" clearable aria-label="搜索机房统计" placeholder="搜索机房统计" style="max-width:360px;margin-bottom:12px"/><el-table :data="summaryPageRows" ref="summaryTable" @sort-change="onSummarySortChange"><el-table-column v-for="k in ['区域','位置','类型','备件','型号','可用','预留','待检测','故障','在途','维修中']" :key="k" :prop="k" :label="k" :width="summaryWidths[k]" sortable="custom"><template #header><TableSortHeader :label="k" :width="summaryWidths[k]" @sort="sortSummaryBy(k)" @resize="resizeSummaryColumn(k,$event)"/></template></el-table-column><template #empty><el-empty :description="summaryQuery?'没有匹配记录':'暂无记录'"><el-button v-if="summaryQuery" @click="clearSummarySearch">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="summaryPage" v-model:page-size="summaryPageSize" :total="summaryTotal" label="机房统计"/></el-tab-pane>
<el-tab-pane label="库存流水" name="movements"><div class="ops-toolbar between"><span class="ops-muted">{{historyTarget?historyTarget.spec.name+' · '+(historyTarget.serialNumber||'数量管理'): "全部备件的入库、调拨、领用与维修记录"}}</span><el-button v-if="historyTarget" @click="historyTarget=null">查看全部</el-button><el-button :disabled="loading||loadFailed" @click="exportHistory">导出流水</el-button></div><SpareMovementTable ref="historyTable" :rows="historyRows" :sites="sites" :stock-id="historyTarget?.id"/></el-tab-pane></el-tabs></el-card>
<el-drawer v-model="settingsOpen" title="备件资料与预警设置" size="min(1050px,96vw)" append-to-body><div class="asset-ops spare-settings"><p class="ops-muted">录入时自动关联规格，无需先来此建资料。这里用于补充兼容信息和设置最低可用数量。</p><el-tabs v-model="settingsTab"><el-tab-pane label="备件规格" name="specs"><div class="ops-toolbar between"><span class="ops-muted">同容量不代表兼容；按接口、代际、规格及料号区分。</span><el-button v-if="canWrite" @click="create('spec')">新增规格</el-button></div><el-input v-model="specSearch" clearable aria-label="搜索备件规格" placeholder="搜索备件规格" style="max-width:360px;margin-bottom:12px"/><el-table :data="specPageRows" ref="specTable" @sort-change="onSpecSortChange"><el-table-column label="名称" prop="name" sortable="custom" :width="specWidths['name']"><template #header><TableSortHeader label="名称" :width="specWidths['name']" @sort="sortSpecBy('name')" @resize="resizeSpecColumn('name',$event)"/></template></el-table-column><el-table-column label="料号 / 管理编码" prop="partNumber" sortable="custom" :width="specWidths['partNumber']"><template #header><TableSortHeader label="料号 / 管理编码" :width="specWidths['partNumber']" @sort="sortSpecBy('partNumber')" @resize="resizeSpecColumn('partNumber',$event)"/></template></el-table-column><el-table-column label="规格" prop="specification" sortable="custom" :width="specWidths['specification']"><template #header><TableSortHeader label="规格" :width="specWidths['specification']" @sort="sortSpecBy('specification')" @resize="resizeSpecColumn('specification',$event)"/></template></el-table-column><el-table-column label="管理方式" prop="trackingLabel" sortable="custom" :width="specWidths['trackingLabel']"><template #header><TableSortHeader label="管理方式" :width="specWidths['trackingLabel']" @sort="sortSpecBy('trackingLabel')" @resize="resizeSpecColumn('trackingLabel',$event)"/></template><template #default="{row}">{{row.tracking==='SERIAL'?'按件 / SN':'按数量'}}</template></el-table-column><el-table-column label="兼容信息" prop="compatibility" sortable="custom" :width="specWidths['compatibility']"><template #header><TableSortHeader label="兼容信息" :width="specWidths['compatibility']" @sort="sortSpecBy('compatibility')" @resize="resizeSpecColumn('compatibility',$event)"/></template></el-table-column><el-table-column v-if="canWrite" label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="editRecord('spec',row)">编辑</el-button><el-button link type="danger" :disabled="busy" @click="removeRecord('spec',row)">删除</el-button></template></el-table-column><template #empty><el-empty :description="specQuery?'没有匹配记录':'暂无记录'"><el-button v-if="specQuery" @click="clearSpecSearch">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="specPage" v-model:page-size="specPageSize" :total="specTotal" label="备件规格"/></el-tab-pane>
<el-tab-pane label="最低库存" name="minimums"><div class="ops-toolbar between"><span class="ops-muted">按位置及规格设置；重新提交同一组合会更新阈值。</span><el-button v-if="canWrite" @click="create('minimum')">设置阈值</el-button></div><el-input v-model="minimumSearch" clearable aria-label="搜索最低库存" placeholder="搜索最低库存" style="max-width:360px;margin-bottom:12px"/><el-table :data="minimumPageRows" ref="minimumTable" @sort-change="onMinimumSortChange"><el-table-column label="位置" prop="site.name" sortable="custom" :width="minimumWidths['site.name']"><template #header><TableSortHeader label="位置" :width="minimumWidths['site.name']" @sort="sortMinimumBy('site.name')" @resize="resizeMinimumColumn('site.name',$event)"/></template><template #default="{row}">{{row.site.name}}</template></el-table-column><el-table-column label="备件" prop="specLabel" sortable="custom" :width="minimumWidths['specLabel']"><template #header><TableSortHeader label="备件" :width="minimumWidths['specLabel']" @sort="sortMinimumBy('specLabel')" @resize="resizeMinimumColumn('specLabel',$event)"/></template><template #default="{row}">{{row.spec.name}} / {{row.spec.specification}}</template></el-table-column><el-table-column label="最低可用数量" prop="minimum" sortable="custom" :width="minimumWidths['minimum']"><template #header><TableSortHeader label="最低可用数量" :width="minimumWidths['minimum']" @sort="sortMinimumBy('minimum')" @resize="resizeMinimumColumn('minimum',$event)"/></template></el-table-column><el-table-column v-if="canWrite" label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="editRecord('minimum',row)">编辑</el-button><el-button link type="danger" :disabled="busy" @click="removeRecord('minimum',row)">删除</el-button></template></el-table-column><template #empty><el-empty :description="minimumQuery?'没有匹配记录':'暂无记录'"><el-button v-if="minimumQuery" @click="clearMinimumSearch">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="minimumPage" v-model:page-size="minimumPageSize" :total="minimumTotal" label="最低库存"/></el-tab-pane>
</el-tabs></div></el-drawer>
<el-drawer v-model="detailOpen" title="备件详情" size="min(1050px,96vw)" append-to-body><div v-if="detailStock" class="asset-ops spare-details"><div class="ops-toolbar between"><strong>{{detailStock.spec.name}} · {{detailStock.serialNumber||'数量管理'}}</strong><el-button v-if="canWrite" @click="editRecord('stock',detailStock)">编辑档案</el-button></div><el-tabs v-model="detailTab"><el-tab-pane label="档案明细" name="info"><el-descriptions :column="2" border><el-descriptions-item label="区域">{{detailStock.site.region}}</el-descriptions-item><el-descriptions-item label="存放位置">{{detailStock.site.name}}</el-descriptions-item><el-descriptions-item label="类型">{{detailStock.spec.category}}</el-descriptions-item><el-descriptions-item label="名称">{{detailStock.spec.name}}</el-descriptions-item><el-descriptions-item label="型号">{{detailStock.spec.modelNumber||'—'}}</el-descriptions-item><el-descriptions-item label="数量">{{detailStock.quantity}} {{detailStock.spec.unit}}</el-descriptions-item><el-descriptions-item label="序列号">{{detailStock.serialNumber||'按数量管理'}}</el-descriptions-item><el-descriptions-item label="状态">{{stockStates[detailStock.state]}}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{detailStock.notes||'—'}}</el-descriptions-item><el-descriptions-item label="具体规格" :span="2">{{detailStock.spec.specification||'—'}}</el-descriptions-item><el-descriptions-item label="料号 / 管理编码">{{detailStock.spec.partNumber||'—'}}</el-descriptions-item><el-descriptions-item label="库位">{{detailStock.bin||'—'}}</el-descriptions-item><el-descriptions-item label="批次">{{detailStock.batch||'—'}}</el-descriptions-item><el-descriptions-item label="保修截止">{{detailStock.warrantyExpiresAt?.slice(0,10)||'—'}}</el-descriptions-item><el-descriptions-item label="安装设备">{{detailStock.installedDevice?.code||'—'}}</el-descriptions-item><el-descriptions-item label="调拨目标">{{sites.find(s=>s.id===detailStock.destinationSiteId)?.name||'—'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="该备件流水" name="history"><SpareMovementTable :rows="detailMovements" :sites="sites" :stock-id="detailStock.id"/><div class="ops-toolbar"><el-button @click="showHistory(detailStock);detailOpen=false">在库存流水页查看</el-button></div></el-tab-pane></el-tabs></div></el-drawer>
<el-dialog v-model="dialog" :title="editing?{spec:'编辑备件规格',stock:'编辑备件档案',minimum:'编辑最低库存'}[kind]:{spec:'新增备件规格',minimum:'设置最低库存',move:moveLabels[form.operation]||'库存操作'}[kind]" width="min(650px,95vw)"><el-form label-position="top"><template v-if="kind==='spec'"><div class="ops-form-grid"><el-form-item v-for="[k,l] in [['name','备件名称'],['category','类别'],['manufacturer','厂商'],['modelNumber','型号'],['partNumber','厂商料号'],['unit','单位']]" :key="k" :label="l"><el-input v-model="form[k]" :disabled="k==='unit'&&specHasStock"/></el-form-item></div><el-form-item label="具体规格"><el-input v-model="form.specification"/></el-form-item><el-form-item label="管理方式"><el-select v-model="form.tracking" :disabled="specHasStock"><el-option label="按件 / SN" value="SERIAL"/><el-option label="按数量" value="QUANTITY"/></el-select></el-form-item><el-form-item label="兼容设备型号（经人工核验）"><el-input v-model="form.compatibility"/></el-form-item></template><template v-if="kind==='stock'||kind==='minimum'"><el-form-item label="备件规格"><el-select v-model="form.specId" filterable :disabled="editing&&(kind==='minimum'||identityLocked)"><el-option v-for="s in specs" :key="s.id" :label="s.name+' / '+s.specification" :value="s.id"/></el-select></el-form-item><el-form-item :label="kind==='stock'?'区域 / 存放位置':'资产位置'"><el-select v-model="form.siteId" :disabled="editing&&(kind==='minimum'||identityLocked)"><el-option v-for="s in sites" :key="s.id" :label="s.region+' / '+s.name" :value="s.id"/></el-select></el-form-item></template><template v-if="kind==='stock'"><div class="ops-form-grid"><el-form-item label="类型"><el-input :model-value="currentSpec?.category||''" disabled/></el-form-item><el-form-item label="名称"><el-input :model-value="currentSpec?.name||''" disabled/></el-form-item><el-form-item label="型号"><el-input :model-value="currentSpec?.modelNumber||''" disabled/></el-form-item><el-form-item label="数量"><el-input :model-value="String(form.quantity??0)" disabled/></el-form-item></div><el-form-item label="状态"><el-input :model-value="stockStates[form.state||'AVAILABLE']" disabled/></el-form-item><el-form-item label="备注"><el-input v-model="form.notes" type="textarea" :rows="2" maxlength="330" show-word-limit placeholder="用途、兼容说明或补充信息"/></el-form-item><el-form-item v-if="specs.find(s=>s.id===form.specId)?.tracking==='SERIAL'" label="SN 序列号"><el-input v-model="form.serialNumber" :disabled="identityLocked"/></el-form-item><div class="ops-form-grid"><el-form-item label="柜位 / 料盒"><el-input v-model="form.bin"/></el-form-item><el-form-item label="批次"><el-input v-model="form.batch"/></el-form-item></div><el-form-item label="保修截止日"><el-date-picker v-model="form.warrantyExpiresAt" value-format="YYYY-MM-DD"/></el-form-item><el-alert title="此处只修正档案信息，数量和状态通过库存操作变更；已有业务时规格、位置和 SN 不可直接改写。" :closable="false"/></template><el-form-item v-if="kind==='minimum'" label="最低可用数量"><el-input-number v-model="form.minimum" :min="0" :precision="0"/></el-form-item><template v-if="kind==='move'"><p>{{current?.spec.name}} · {{current?.serialNumber||current?.spec.partNumber}} · 当前 {{current?.quantity}} {{current?.spec.unit}}</p><el-alert v-if="form.operation==='TRANSFER'" title="发出后转为在途，不计入可用库存；目标位置确认收货后才变为可用。" :closable="false"/><el-alert v-if="form.operation==='FAULT'" :title="'将当前记录整批 '+current?.quantity+' 件标记故障，不再计入可用库存。'" :closable="false"/><el-alert v-if="form.operation==='RECEIVE'" :title="'收货位置：'+(sites.find(s=>s.id===current?.destinationSiteId)?.name||current?.site.name)+'；确认后本批数量转入可用库存。'" :closable="false"/><el-form-item label="本次数量"><el-input-number v-model="form.quantity" :min="1" :disabled="['RECEIVE','RESERVE','RELEASE','PASS','FAULT','REPAIR','RETIRE'].includes(form.operation)" :max="current?.spec.tracking==='SERIAL'?1:form.operation==='IN'?1000000:current?.quantity" :precision="0"/></el-form-item><el-form-item v-if="form.operation==='INSTALL'" label="目标设备"><el-select v-model="form.deviceId" filterable><el-option v-for="a in devices" :key="a.device.id" :label="a.device.code+' / '+a.device.name" :value="a.device.id"/></el-select></el-form-item><el-form-item v-if="form.operation==='TRANSFER'" label="目标位置"><el-select v-model="form.destinationSiteId"><el-option v-for="s in sites.filter(s=>s.id!==current?.siteId)" :key="s.id" :label="s.region+' / '+s.name" :value="s.id"/></el-select></el-form-item><el-form-item v-if="form.operation==='RETIRE'" label="数据处置依据 / 非存储介质确认"><el-input v-model="form.disposalEvidence"/></el-form-item><el-form-item label="操作事由 / 依据"><el-input v-model="form.reason" type="textarea"/></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">{{kind==='move'?form.operation==='TRANSFER'?'发出调拨':form.operation==='RECEIVE'?'确认收货':form.operation==='IN'?'确认入库':'确认办理':'确认保存'}}</el-button></template></el-dialog><SpareReceiptDialog v-model="receiptDialog" :specs="specs" :sites="sites" @saved="load"/></div></template>

<style scoped>.spare-details :deep(.el-descriptions__content){overflow-wrap:anywhere}.spare-settings,.spare-details{padding-bottom:24px}</style>
